  /* 词表页：恢复成内置默认标签库；题上已经贴的标签不摘 */
  function restoreDefaultVocab() {
    if (typeof confirm === 'function' && !confirm('把考点词表恢复成内置默认的 ' + DEFAULT_VOCAB.length + ' 个？\n你后来加的自定义考点会从词表移除；题上已经贴的标签不会摘掉。')) return;
    TAGV = withBasics(DEFAULT_VOCAB.slice());
    /* 恢复默认 = 显式重新加回来，撤掉这些词的删除墓碑 */
    if (typeof tombDel === 'function') {
      DEFAULT_VOCAB.concat(BASIC_TAGS).forEach(function (t) { try { tombDel('vocab', t); } catch (e) {} });
    }
    saveVocab();
    TAGS_STATS_CACHE = null;
    if (typeof toast === 'function') toast('已恢复默认词表：' + DEFAULT_VOCAB.length + ' 个考点');
    if (typeof render === 'function') { try { render(); } catch (e) {} }
  }

  function tagsOf(k) { var v = TAGD[k]; return Array.isArray(v) ? v.slice() : []; }
  function userTagsOf(k) { return tagsOf(k).filter(function (t) { return BASIC_TAGS.indexOf(t) < 0; }); }
  function setTags(k, list, quiet) {
    list = norm(list);
    var bs = list.filter(function (t) { return BASIC_TAGS.indexOf(t) >= 0; });
    var us = list.filter(function (t) { return BASIC_TAGS.indexOf(t) < 0; });
    list = bs.slice(0, 1).concat(us).slice(0, MAX_PER_Q);   /* 六科最多一科 */

    if (!list.length) {
      delete TAGD[k];
      if (typeof tombAdd === 'function') tombAdd('tag', k);   /* 记墓碑：别被另一个标签页的合并复活 */
    } else {
      TAGD[k] = list;
      /* 重新给题打上标签 = 反向操作，把墓碑撤掉，不然 mergeWrite 会把这条当「已删」再丢一次 */
      if (typeof tombDel === 'function') { try { tombDel('tag', k); } catch (e) {} }
    }
    save();
    if (typeof bumpHay === 'function') { try { bumpHay(); } catch (e) {} }
    if (!quiet) drawTags();
    return list;
  }
  function addTags(k, list) { return setTags(k, tagsOf(k).concat(list)); }
  function delTag(k, t) { return setTags(k, tagsOf(k).filter(function (x) { return x !== t; })); }
  function setBasic(k, subject) {
    if (BASIC_TAGS.indexOf(subject) < 0) return null;
    var us = tagsOf(k).filter(function (t) { return BASIC_TAGS.indexOf(t) < 0; });
    return setTags(k, [subject].concat(us), false);
  }
  function clearBasic(k) {
    var us = tagsOf(k).filter(function (t) { return BASIC_TAGS.indexOf(t) < 0; });
    return setTags(k, us, false);
  }
  function rememberVocab(list) {
    var added = 0;
    norm(list).forEach(function (t) {
      if (TAGV.indexOf(t) < 0) { TAGV.push(t); added++; }
      /* 重新加回来 = 撤销「删词」墓碑，不然同步时会被自己挡掉 */
      if (typeof tombDel === 'function') { try { tombDel('vocab', t); } catch (e) {} }
    });
    if (added) saveVocab();
    return added;
  }
  function dropTagEverywhere(t) {
    if (BASIC_TAGS.indexOf(t) >= 0) {
      if (typeof toast === 'function') toast('「' + t + '」是基本标签，不能从词表删除');
      return 0;
    }
    var n = 0;
    Object.keys(TAGD).forEach(function (k) {
      if (tagsOf(k).indexOf(t) >= 0) { setTags(k, tagsOf(k).filter(function (x) { return x !== t; }), true); n++; }
    });
    TAGV = TAGV.filter(function (x) { return x !== t; });
    /* 词表删词也要立墓碑：同步时词表取并集，不然另一台设备会把它加回来 */
    if (typeof tombAdd === 'function') { try { tombAdd('vocab', t); } catch (e) {} }
    saveVocab();
    return n;
  }
  function dropTagsOfBank(bankId) {
    var pre = bankId + '#', n = 0;
    Object.keys(TAGD).forEach(function (k) { if (k.indexOf(pre) === 0) { setTags(k, [], true); n++; } });
    TAGS_STATS_CACHE = null;
    return n;
  }
  /* 一键清除：词表 + 所有题上的标签一起清。
     不能只把 TAGD 置空就 save() —— mergeWrite 会把存档里的旧标签又合回来，
     所以先用 tombWipe('tag') 立一道「整表已清」的墓碑，再写空。 */
  function clearAllTags() {
    var n = TAGV.filter(function (t) { return BASIC_TAGS.indexOf(t) < 0; }).length, used = 0;
    var keep = {}, cleared = [];
    Object.keys(TAGD).forEach(function (k) {
      var ts = tagsOf(k);
      if (!ts.length) return;
      var bs = ts.filter(function (t) { return BASIC_TAGS.indexOf(t) >= 0; });
      if (bs.length) keep[k] = bs;
      if (bs.length !== ts.length) {
        used++;
        if (!bs.length) cleared.push(k);   /* 只给「清完就没标签」的题立墓碑；留了基本科的题靠本机优先挡住云端 */
      }
    });
    /* 整表 wipe 仍然要立：否则云同步 / 另一个页签会把用户标签合并回来。
       同时给每题立墓碑 —— 只靠 wipe 的话，旧版同步合并不看 wipe，仍会复活。 */
    if (typeof tombWipe === 'function') { try { tombWipe('tag'); } catch (e) {} }
    if (typeof tombWipe === 'function') { try { tombWipe('vocab'); } catch (e) {} }
    if (typeof tombAdd === 'function') cleared.forEach(function (k) { try { tombAdd('tag', k); } catch (e) {} });
    Object.keys(TAGD).forEach(function (k) { delete TAGD[k]; });
    Object.keys(keep).forEach(function (k) { TAGD[k] = keep[k]; });
    save();
    TAGV = BASIC_TAGS.slice();
    saveVocab();
    if (typeof bumpHay === 'function') { try { bumpHay(); } catch (e) {} }
    TAGS_STATS_CACHE = null;
    if (typeof render === 'function') { try { render(); } catch (e) {} }
    if (typeof toast === 'function') {
      toast('已清空 ' + n + ' 个用户标签' + (used ? ('，摘掉 ' + used + ' 道题上的用户标签') : '') + '；六大基本标签保留', 2600, 'ok');
    }
  }
  function askClearAll() {
    if (JOB.running) {
      if (typeof toast === 'function') toast('AI 正在打标签，先点「停止」再清空', 2400, 'bad');
      return;
    }
    var used = Object.keys(TAGD).filter(function (k) {
      return tagsOf(k).some(function (t) { return BASIC_TAGS.indexOf(t) < 0; });
    }).length;
    var userN = TAGV.filter(function (t) { return BASIC_TAGS.indexOf(t) < 0; }).length;
    var msg = '清空用户考点词表（' + userN + ' 个）'
      + (used ? ('，并摘掉 ' + used + ' 道题上的用户标签') : '') + '？\n六大基本标签会保留；这个操作不能撤销。';
    if (!confirm(msg)) return;
    clearAllTags();
  }
  /* 只摘掉题上已打的用户考点标签：词表和六科基本标签都保留。
     和 clearAllTags 一样走整表 wipe，防止 mergeWrite 把旧标签合回来。 */
  function clearAppliedTags() {
    var used = 0, keep = {}, cleared = [];
    Object.keys(TAGD).forEach(function (k) {
      var ts = tagsOf(k);
      if (!ts.length) return;
      var bs = ts.filter(function (t) { return BASIC_TAGS.indexOf(t) >= 0; });
      var us = ts.filter(function (t) { return BASIC_TAGS.indexOf(t) < 0; });
      if (bs.length) keep[k] = bs;      /* 只有基本标签的题也要保留基本标签 */
      if (us.length) {
        used++;
        if (!bs.length) cleared.push(k);   /* 只给清完就没标签的题立墓碑 */
      }
    });
    if (typeof tombWipe === 'function') { try { tombWipe('tag'); } catch (e) {} }
    if (typeof tombAdd === 'function') cleared.forEach(function (k) { try { tombAdd('tag', k); } catch (e) {} });
    Object.keys(TAGD).forEach(function (k) { delete TAGD[k]; });
    Object.keys(keep).forEach(function (k) { TAGD[k] = keep[k]; });
    save();
    if (typeof bumpHay === 'function') { try { bumpHay(); } catch (e) {} }
    TAGS_STATS_CACHE = null;
    if (typeof render === 'function') { try { render(); } catch (e) {} }
    if (typeof toast === 'function') toast('已清除 ' + used + ' 道题上的考点标签；词表和六科基本标签保留', 2600, 'ok');
  }
  function askClearApplied() {
    if (JOB.running) {
      if (typeof toast === 'function') toast('AI 正在打标签，先点「停止」再清空', 2400, 'bad');
      return;
    }
    var used = Object.keys(TAGD).filter(function (k) {
      return tagsOf(k).some(function (t) { return BASIC_TAGS.indexOf(t) < 0; });
    }).length;
    if (!used) { if (typeof toast === 'function') toast('还没有打过考点标签'); return; }
    var msg = '清除所有题上已经打的考点标签（' + used + ' 道题）？\n考点词表和六大基本标签都会保留；这个操作不能撤销。';
    if (!confirm(msg)) return;
    clearAppliedTags();
  }

  /* ---------- 统计：按考点 ---------- */
  var TAGS_STATS_CACHE = null;
  /* 按考点统计。sub 为空 = 全部；否则只算这个基本学科（'__none' = 还没分科的题）。
     只统计用户考点标签，六科本身当作第一排筛选，不再混进下面的排行里。 */
  function tagStats(sub) {
    sub = sub || '';
    if (!sub && TAGS_STATS_CACHE) return TAGS_STATS_CACHE;
    var banks = [];
    try { banks = (typeof baseBanks === 'function') ? baseBanks() : []; } catch (e) { banks = []; }
    var map = {};
    var tagged = 0, total = 0;
    banks.forEach(function (b) {
      (b.questions || []).forEach(function (q) {
        var k = keyOf(b, q);
        var ts = tagsOf(k);
        var bs = ts.filter(function (t) { return BASIC_TAGS.indexOf(t) >= 0; });
        if (sub) {
          if (sub === '__none') { if (bs.length) return; }
          else if (bs.indexOf(sub) < 0) return;
        }
        total++;
        var us = ts.filter(function (t) { return BASIC_TAGS.indexOf(t) < 0; });
        if (!us.length) return;
        tagged++;
        var a = (typeof ANS !== 'undefined' && ANS) ? ANS[k] : null;
        var done = !!(a && !a.redo), ok = !!(done && a.ok), wr = a ? (a.wrong || 0) : 0;
        us.forEach(function (t) {
          var r = map[t] = map[t] || { t: t, n: 0, done: 0, ok: 0, wrong: 0, keys: [] };
          r.n++; r.keys.push(k);
          if (done) { r.done++; if (ok) r.ok++; }
          r.wrong += wr;
        });
      });
    });
    var rows = Object.keys(map).map(function (t) {
      var r = map[t];
      r.acc = r.done ? Math.round(r.ok / r.done * 100) : 0;
      r.thin = r.done < 5;                     /* 样本不足 */
      return r;
    });
    /* 排法：能用的在前（样本够的先看），同组里正确率低的在上，再按错得多的 */
    rows.sort(function (a, b) {
      return (a.thin ? 1 : 0) - (b.thin ? 1 : 0) || a.acc - b.acc || b.wrong - a.wrong || b.n - a.n ||
        String(a.t).localeCompare(String(b.t), 'zh');
    });
    var out = { rows: rows, tagged: tagged, total: total, tags: rows.length, sub: sub };
    if (!sub) TAGS_STATS_CACHE = out;
    return out;
  }
  /* 六科筛选行用：每个科里「打了考点标签的题」有多少道 */
  function tagSubjectCounts() {
    var banks = [];
    try { banks = (typeof baseBanks === 'function') ? baseBanks() : []; } catch (e) { banks = []; }
    var out = { all: 0, none: 0, subs: {} };
    banks.forEach(function (b) {
      (b.questions || []).forEach(function (q) {
        var ts = tagsOf(keyOf(b, q));
        var us = ts.filter(function (t) { return BASIC_TAGS.indexOf(t) < 0; });
        if (!us.length) return;
        out.all++;
        var bs = ts.filter(function (t) { return BASIC_TAGS.indexOf(t) >= 0; });
        var s = bs[0] || '__none';
        if (s === '__none') out.none++;
        else out.subs[s] = (out.subs[s] || 0) + 1;
      });
    });
    return out;
  }
  function weakestKeys(n, sub) {
    var st = sub ? tagStats(sub) : (TAGS_STATS_CACHE || tagStats());
    var pick = st.rows.filter(function (r) { return !r.thin || !st.rows.some(function (x) { return !x.thin; }); }).slice(0, n || 3);
    var keys = [], seen = {};
    pick.forEach(function (r) { r.keys.forEach(function (k) { if (!seen[k]) { seen[k] = 1; keys.push(k); } }); });
    return { keys: keys, tags: pick.map(function (r) { return r.t; }) };
  }

  function normalizeBasics() {
    var dirty = false;
    Object.keys(TAGD).forEach(function (k) {
      var ts = tagsOf(k);
      var bs = ts.filter(function (t) { return BASIC_TAGS.indexOf(t) >= 0; });
      if (bs.length > 1) {
        TAGD[k] = [bs[0]].concat(ts.filter(function (t) { return BASIC_TAGS.indexOf(t) < 0; }));
        dirty = true;
      }
    });
    if (dirty) { save(); if (typeof bumpHay === 'function') { try { bumpHay(); } catch (e) {} } }
  }

  /* ---------- 答题页那一行标签 ---------- */
  function toggleHideTags() {
    HIDE_TAGS = !HIDE_TAGS;
    try { localStorage.setItem(HIDE_KEY, HIDE_TAGS ? '1' : '0'); } catch (e) {}
    return HIDE_TAGS;
  }
  function rowHtml(k, q) {
    if (HIDE_TAGS) {
      return '<div class="tagrow tagrow-hidden" data-tagk="' + esc(k) + '">'
        + '<span class="taghide-note"><span class="taghide-ic">🙈</span>标签已隐藏 · 先做题</span>'
        + '<button type="button" class="taghide-btn show" data-taghide="1" title="显示基本标签和考点标签">显示标签</button>'
        + '</div>';
    }
    var ts = tagsOf(k);
    var bs = ts.filter(function (t) { return BASIC_TAGS.indexOf(t) >= 0; });
    var us = ts.filter(function (t) { return BASIC_TAGS.indexOf(t) < 0; });
    var basicChips = bs.map(function (t) {
      return '<span class="tagchip basic" data-tagedit="1" title="基本标签（固定名称）；点「＋ 标签」可以挂上 / 去掉">' + esc(t) + '</span>';
    }).join('');
    var chips = us.map(function (t) {
      return '<button class="tagchip" data-tagdel="' + esc(t) + '" title="点一下去掉这个标签">' + esc(t) + '<i>×</i></button>';
    }).join('');
    var none = us.length ? '' : '<span class="tag-none">' + (bs.length ? '无自定义标签' : '还没打考点标签') + '</span>';
    return '<div class="tagrow" data-tagk="' + esc(k) + '">'
      + (bs.length ? '<span class="tag-lab">基本</span>' + basicChips : '')
      + '<span class="tag-lab">考点</span>' + chips + none
      + '<button class="tagadd" data-tagedit="1" title="加考点标签（基本标签在上面单独选，自定义标签在这里加）">＋ 标签</button>'
      + '<button class="tagadd tagai" data-tagai="1" title="让 AI 从词表里给这道题挑 1–3 个考点">AI 标签</button>'
      + '<button type="button" class="taghide-btn hide" data-taghide="1" title="隐藏标签，防止提前看到考什么"><span class="taghide-ic">👁</span>隐藏</button>'
      + '</div>';
  }
  function editorHtml(k) {
    var cur = tagsOf(k);
    var curUser = cur.filter(function (t) { return BASIC_TAGS.indexOf(t) < 0; });
    var userVocab = TAGV.filter(function (t) { return BASIC_TAGS.indexOf(t) < 0; });
    var sug = userVocab.filter(function (t) { return curUser.indexOf(t) < 0; });
    var basicRow = '<div class="basic-seg tag-basic-row"><span class="basic-seg-label">基本</span>'
      + '<div class="basic-seg-opts">'
      + BASIC_TAGS.map(function (t) {
          var on = cur.indexOf(t) >= 0;
          return '<button type="button" class="basic-opt' + (on ? ' on' : '') + '" data-basictag="' + esc(t) + '" title="六大基本标签，六选一；再点选中的可以取消">'
            + esc(t) + '</button>';
        }).join('') + '</div></div>';
    return '<div class="tagedit" data-tageditbox="' + esc(k) + '">'
      + '<div class="tedit-top">给这道题挂考点标签<span class="small muted">（基本 6 个在上面单独选；自定义考点回车或点「加」；整个题库的词表去<b>学习统计 → 按考点</b>）</span></div>'
      + basicRow
      + '<div class="tedit-cur">' + (curUser.length ? curUser.map(function (t) {
        return '<button class="tagchip" data-tagdel="' + esc(t) + '">' + esc(t) + '<i>×</i></button>';
      }).join('') : '<span class="small muted">还没有自定义标签</span>') + '</div>'
      + '<div class="tedit-in"><input class="inp tedit-input" placeholder="打一个自定义考点，比如：炎症" list="tagVocabList" maxlength="32">'
      + '<button class="btn tiny primary" data-tagadd="1">加</button>'
      + '<button class="btn tiny" data-tagclose="1">收起</button></div>'
      + '<datalist id="tagVocabList">' + userVocab.map(function (t) { return '<option value="' + esc(t) + '"></option>'; }).join('') + '</datalist>'
      + (sug.length ? '<div class="tedit-sug">词表里还有：' + sug.slice(0, 24).map(function (t) {
        return '<button class="vocab-chip" data-tagadd="' + esc(t) + '">' + esc(t) + '</button>';
      }).join('') + (sug.length > 24 ? '<span class="small muted">…共 ' + sug.length + ' 个（统计页能看全部）</span>' : '') + '</div>'
        : '<div class="tedit-sug small muted">还没有自定义词条：统计页有「批量导入 / 让 AI 起一份」，或者你直接打字（打过的会自动进词表）。</div>')
      + '</div>';
  }
  /* 就地重画：只动标签行/编辑框，不整页重画 —— 免得把正在生成的东西冲掉 */
  function drawTags() {
    var row = document.querySelector('.tagrow[data-tagk]');
    if (!row) return;
    var k = row.getAttribute('data-tagk');
    var box = row.querySelector('.tagedit');
    /* rowHtml 在隐藏时返回的是另一套外层结构；只换 innerHTML 会漏掉 tagrow-hidden 类 */
    row.classList.toggle('tagrow-hidden', HIDE_TAGS);
    row.innerHTML = rowHtml(k).replace(/^<div class="tagrow[^"]*"[^>]*>/, '').replace(/<\/div>$/, '');
    if (box) openEdit(k, true);
  }
  function openEdit(k, keep) {
    var row = document.querySelector('.tagrow[data-tagk="' + cssq(k) + '"]');
    if (!row) return;
    var old = row.querySelector('.tagedit');
    if (old && keep) return;
    if (old) old.remove();
    else row.insertAdjacentHTML('beforeend', editorHtml(k));
    var inp = row.querySelector('.tedit-input');
    if (inp) setTimeout(function () { try { inp.focus(); } catch (e) {} }, 30);
  }
  function closeEdit(k) {
    var row = document.querySelector('.tagrow[data-tagk="' + cssq(k) + '"]');
    if (!row) return;
    var b = row.querySelector('.tagedit');
    if (b) b.remove();
  }
  function cssq(s) { return String(s == null ? '' : s).replace(/["\\]/g, '\\$&'); }

  function bindRow(host, bank, q) {
    if (!host) return;
    /* 套卷里的题用的是原题 key（和解析 / 收藏同一套），标签行也按它绑 */
    var k = (bank.paper && q._srcKey) ? q._srcKey : keyOf(bank, q);
    var row = host.querySelector('.tagrow[data-tagk="' + cssq(k) + '"]');
    if (!row) return;
    row.addEventListener('click', function (e) {
      if (e.target.closest('[data-taghide]')) {
        e.preventDefault(); e.stopPropagation();
        toggleHideTags();
        drawTags();
        return;
      }
      var del = e.target.closest('[data-tagdel]');
      if (del) { delTag(k, del.getAttribute('data-tagdel')); return; }
      var bs = e.target.closest('[data-basictag]');
      if (bs) {
        var tb = bs.getAttribute('data-basictag');
        var curB = tagsOf(k).filter(function (t) { return BASIC_TAGS.indexOf(t) >= 0; })[0] || '';
        if (curB === tb) clearBasic(k); else setBasic(k, tb);
        rememberVocab([tb]);
        /* 刷题页正按六科/未选筛着：当场刷新计数，标完最后一题自动回全选 */
        try { if (typeof refreshQuizChips === 'function') refreshQuizChips(); } catch (e) {}
        return;
      }
      var add = e.target.closest('[data-tagadd]');
      if (add) {
        var v = add.getAttribute('data-tagadd');
        if (v && v !== '1') { addTags(k, [v]); rememberVocab([v]); return; }
        var inp = row.querySelector('.tedit-input');
        var t = inp ? inp.value : '';
        if (!t) { if (inp) inp.focus(); return; }
        addTags(k, [t]); rememberVocab([t]);
        if (inp) { inp.value = ''; inp.focus(); }
        return;
      }
      if (e.target.closest('[data-tagai]')) {
        if (!TAGV.length) { if (typeof toast === 'function') toast('词表是空的：先去「学习统计 → 按考点」导入，或让 AI 起一份'); return; }
        if (JOB.running) { if (typeof toast === 'function') toast('AI 正在批量打标签，等它跑完再试'); return; }
        if (typeof toast === 'function') toast('AI 正在读这道题…', 1600);
        aiTagOne(bank.id, q.id, k).then(function (r) {
          if (r && r.ok) {
            /* 以存储为准重画一次这一行：避免别的页签 / 合并写入让界面停在旧状态 */
            try { if (typeof window.tagReload === 'function') window.tagReload(); drawTags(); } catch (e) {}
            if (typeof toast === 'function') toast('AI 已给这道题打上：' + r.tags.join('、'));
          } else if (typeof toast === 'function') toast((r && r.err) || 'AI 打标签失败', 3000, 'bad');
        });
        return;
      }
      if (e.target.closest('[data-tagedit]')) { openEdit(k); return; }
      if (e.target.closest('[data-tagclose]')) { closeEdit(k); return; }
    });
    row.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' && e.target && e.target.classList.contains('tedit-input')) {
        e.preventDefault(); e.stopPropagation();
        var t = e.target.value;
        if (t) { addTags(k, [t]); rememberVocab([t]); e.target.value = ''; }
      } else if (e.key === 'Escape' && e.target && e.target.classList.contains('tedit-input')) {
        e.preventDefault(); e.stopPropagation(); closeEdit(k);
      }
    });
  }

