      + '已内置六科分类特征库（不在界面展开）；未分科的优先分；需要时可以把已分科的也全部重分；用户考点标签会保留；中途可以停。</div>'
      + '<div class="tools" style="margin:0">'
      + bankScopeHtml('basicScope')
      + '<button class="btn tiny primary" id="basicGo"' + (todo ? '' : ' disabled') + '>' + (todo ? '一键分六科标签（' + todo + ' 题）' : '全部已分好') + '</button>'
      + (total ? '<button class="btn tiny" id="basicRedo" title="覆盖现有基本标签重新分六科；用户考点标签不动">全部重分（' + total + ' 题）</button>' : '')
      + '<button class="btn tiny" id="basicStop" style="display:none">停止</button>'
      + '<span class="spacer-grow"></span><span class="tl" id="basicState">' + (BJOB.note || '') + '</span></div></div>';
